// ========================================
// 🤖 AI CONFIDENCE COACH
// Extract data from Chat Trigger
// ========================================

const input = $input.first().json;

// ========================================
// USER MESSAGE
// ========================================

const userMessage =
  input.chatInput ??
  input.message ??
  input.text ??
  '';


// ========================================
// USER / SESSION ID
// ========================================

const userId =
  input.userId ??
  input.user_id ??
  input.sessionId ??
  input.session_id ??
  null;


// ========================================
// CURRENT TIMESTAMP - INDIA
// ========================================

const now = new Date();

const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hourCycle: 'h23'
}).formatToParts(now);

const getPart = (type) =>
  parts.find(part => part.type === type)?.value;

const timestamp =
  `${getPart('year')}-${getPart('month')}-${getPart('day')} ` +
  `${getPart('hour')}:${getPart('minute')}:${getPart('second')}`;


// ========================================
// RETURN DATA
// ========================================

return [
  {
    json: {
      user_id: userId,
      user_message: userMessage,
      timestamp: timestamp,
      timezone: 'Asia/Kolkata'
    }
  }
];

// ==========================================
// 🤖 AI CONFIDENCE COACH
// PROFILE MANAGER
// ==========================================


// ==========================================
// 1. GET USER INPUT FROM FIRST CODE NODE
// ==========================================

const original = $('🧩 Extract Chat Input').first().json;

const userId = original.user_id || '';
const userMessage = (original.user_message || '').trim();
const timestamp = original.timestamp || '';


// ==========================================
// 2. GET USER PROFILE FROM GOOGLE SHEETS
// ==========================================

const sheetItems = $input.all();

let profile = null;

if (sheetItems.length > 0) {
  profile = sheetItems[0].json;
}


// ==========================================
// 3. CHECK IF USER ALREADY EXISTS
// ==========================================

const existingUser =
  profile &&
  profile.user_id &&
  String(profile.user_id).trim() !== '';


// ==========================================
// 4. HELPER FUNCTION
// ==========================================

function clean(value) {
  if (value === undefined || value === null) {
    return '';
  }

  return String(value).trim();
}


// ==========================================
// 5. NEW USER
// ==========================================

if (!existingUser) {

  return [
    {
      json: {

        user_id: userId,

        user_message: userMessage,

        timestamp: timestamp,

        user_status: 'new_user',

        name: '',

        career_stage: '',

        challenge: '',

        goal: '',

        onboarding_step: 'name',

        profile_complete: false,

        missing_field: 'name',

        next_question:
          "Hi! 👋 I'm your AI Confidence Coach. What's your name?"
      }
    }
  ];
}


// ==========================================
// 6. EXISTING USER
// ==========================================

let name = clean(profile.name);

let careerStage = clean(profile.career_stage);

let challenge = clean(profile.challenge);

let goal = clean(profile.goal);

let onboardingStep = clean(profile.onboarding_step);


// ==========================================
// 7. SAVE CURRENT ANSWER
// ==========================================

if (onboardingStep === 'name' && !name) {

  name = userMessage;

  onboardingStep = 'career_stage';

}

else if (onboardingStep === 'career_stage' && !careerStage) {

  careerStage = userMessage;

  onboardingStep = 'challenge';

}

else if (onboardingStep === 'challenge' && !challenge) {

  challenge = userMessage;

  onboardingStep = 'goal';

}

else if (onboardingStep === 'goal' && !goal) {

  goal = userMessage;

  onboardingStep = 'completed';

}


// ==========================================
// 8. CHECK PROFILE COMPLETION
// ==========================================

const profileComplete =
  name !== '' &&
  careerStage !== '' &&
  challenge !== '' &&
  goal !== '';


// ==========================================
// 9. FIND NEXT MISSING FIELD
// ==========================================

let missingField = '';

let nextQuestion = '';


if (!name) {

  missingField = 'name';

  nextQuestion =
    "What's your name?";

}

else if (!careerStage) {

  missingField = 'career_stage';

  nextQuestion =
    `Nice to meet you, ${name}! 👋 What is your current career stage? For example: Student, Job Seeker, Working Professional, or Entrepreneur.`;

}

else if (!challenge) {

  missingField = 'challenge';

  nextQuestion =
    "What is the main confidence challenge you're facing right now?";

}

else if (!goal) {

  missingField = 'goal';

  nextQuestion =
    "What is your main goal? What would you like to become more confident at?";

}

else {

  missingField = '';

  nextQuestion = '';

  onboardingStep = 'completed';

}


// ==========================================
// 10. FINAL OUTPUT
// ==========================================

return [
  {
    json: {

      user_id: userId,

      user_message: userMessage,

      timestamp: timestamp,

      user_status: 'existing_user',

      name: name,

      career_stage: careerStage,

      challenge: challenge,

      goal: goal,

      onboarding_step: onboardingStep,

      profile_complete: profileComplete,

      missing_field: missingField,

      next_question: nextQuestion

    }
  }
];
